// Light levels: a lit room is warm white, a cove can carry a colour.
const COVE_RGB = { media_room: [130, 80, 255], games_room: [0, 200, 170], loft: [255, 140, 60], living_room: [255, 170, 90] };
// How much of each room is lit by day; after dark everything lived in is.
const DAY_LIT = { kitchen: 1, living_room: 0.5, foyer: 1, study: 1, media_room: 1, games_room: 0.6, larder: 1, office: 0.6 };
const NIGHT_LIT = { primary_bedroom: 0.4, ensuite: 0.5, walk_in_closet: 0, dressing_room: 0, bathroom: 0.5, garage: 0, workshop: 0.3,
                    laundry: 0, powder_room: 0.5 };

/** A steady number in [0, 1) from a string: the same house at every load. */
function steady(s){
  let h = 2166136261;
  for (const c of s) h = Math.imul(h ^ c.charCodeAt(0), 16777619);
  return ((h >>> 0) % 1000) / 1000;
}

export function estateFixture(q){
  const night = q.get("night") === "1";
  const MODEL = {
    floors: [{ id: "lower", name: "Lower", level: -1, floor_to_floor_m: 2.9 }, { id: "main", name: "Main", level: 0, floor_to_floor_m: 2.9 },
             { id: "upper", name: "Upper", level: 1, floor_to_floor_m: 2.7 }],
    floor_elevations: { lower: -2.9, main: 0, upper: 2.9 },
    room_geometry_m: Object.fromEntries(Object.entries(ROOMS).map(([n, g]) => [n, { type: "poly", ...g }])),
    room_meta: ROOM_META,
    light_positions_m: DEVICES,
    rf_barriers_m: BARRIERS,
    scanner_positions_m: SCANNERS, scanners: {},
  };
  const ago = (min) => new Date(Date.now() - min * 60e3).toISOString();
  const S = (state, fn, a = {}, min = 60) => ({ state, attributes: { friendly_name: fn, ...a }, last_changed: ago(min), last_updated: ago(min), last_reported: ago(Math.min(min, 3)) });
  const STATES = {};
  for (const [eid, [kind, name, room]] of Object.entries(STATE_OF)) {
    const r = room.toLowerCase().replace(/[^a-z0-9]+/g, "_"), k = steady(eid);
    if (kind === "light") {
      const lit = night ? (NIGHT_LIT[r] ?? 0.85) : (DAY_LIT[r] ?? 0);
      const cove = eid.includes("_cove_");
      STATES[eid] = k < lit ? S("on", name, { brightness: Math.round(140 + 115 * steady(eid + "b")),
                                               ...(cove && COVE_RGB[r] ? { rgb_color: COVE_RGB[r] } : { color_temp_kelvin: 2700 }) }, 20 + 200 * k)
        : S("off", name, {}, 30 + 300 * k);
    } else if (kind === "temperature") STATES[eid] = S((20.5 + 2.5 * k).toFixed(1), name, { device_class: "temperature", unit_of_measurement: "°C" });
    else if (kind === "humidity") STATES[eid] = S(String(Math.round(38 + 17 * k)), name, { device_class: "humidity", unit_of_measurement: "%" });
    else if (kind === "lock") STATES[eid] = S("locked", name, {}, 90);
    else if (kind === "garage_door") STATES[eid] = S("off", name, { device_class: "garage_door" }, 240);
    else STATES[eid] = S("off", name, { device_class: kind }, 5 + 60 * k);
  }
  STATES["sun.sun"] = { state: night ? "below_horizon" : "above_horizon", attributes: { elevation: night ? -20 : 35, azimuth: 200 }, last_changed: ago(30) };
  STATES["weather.home"] = S(q.get("sky") || "partlycloudy", "Home", { temperature: 12 });
  const HOUSE3D = { pieces: PIECES };
  return { MODEL, STATES, HOUSE3D, WALKERS, MOTION };
}
